  dm_compose_text: null,
  dm_recipient_ids: null,
  dm_initial_message: null,
  created_dm_id: null,
  profile_display_name: null,
  profile_title: null,
  profile_timezone: null,
  profile_updated: null,
};

type AppContextType = {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  updateState: (updates: Partial<AppState>) => void;
};

const FsmContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider = ({ children }: { children: ReactNode }) => {
  const [state, setState] = useState<AppState>(initialState);

  const updateState = (updates: Partial<AppState>) => {
    setState((prev) => ({ ...prev, ...updates }));
  };

  return (
    <FsmContext.Provider value={{ state, setState, updateState }}>
      {children}
    </FsmContext.Provider>
  );
};

export const useAppContext = () => {
  const context = useContext(FsmContext);
  if (!context) {
    throw new Error('useAppContext must be used within an AppProvider');
  }
  return context;
};
