import { useNavigate } from 'react-router-dom';
import { useAppContext } from '../store/FsmContext';

export default function WorkspaceList() {
  const navigate = useNavigate();
  const { state, updateState } = useAppContext();

  const [filterValue, setFilterValue] = useState('');
  const [searchValue, setSearchValue] = useState('');

  const handleLocationPermission = () => {
    if (state.location_permission_granted === null) {
      updateState({ location_permission_granted: true });
    }
  };

  const handleApplyFilters = () => {
    updateState({ workspace_list_filters_applied: true });
  };

  const handleOpenFiltered = (teamId: string) => {
    if (state.workspace_list_filters_applied === true) {
      updateState({ workspace_list_filters_applied: null, selected_team_id: teamId });
      navigate('/CHANNEL_LIST');
    }
  };

  const handleSearch = () => {
    updateState({ matched_team_id: 'team_matched_1', workspace_list_has_searched: true });
  };

  const handleOpenMatched = (teamId: string) => {
    if (state.matched_team_id && state.workspace_list_has_searched === true) {
      updateState({ selected_team_id: teamId, workspace_list_has_searched: null });
      navigate('/CHANNEL_LIST');
    }
  };

  const handleScrollIntoView = () => {
    updateState({ workspace_list_viewport_anchor_id: 'team_anchor_1' });
  };

  const handleOpenAny = (teamId: string) => {
    if (state.workspace_list_viewport_anchor_id) {
      updateState({ selected_team_id: teamId, workspace_list_viewport_anchor_id: null });
      navigate('/CHANNEL_LIST');
    }
  };

  const handleBackHome = () => {
    navigate('/HOME');
  };

  return (
    <div className="min-h-screen bg-slate-100 p-8 flex flex-col space-y-6">
      <header className="flex justify-between items-center bg-white p-4 shadow-sm rounded-md">
        <h1 className="text-2xl font-bold text-slate-800">Workspaces</h1>
        <button 
          id="back-home"
          onClick={handleBackHome}
          className="text-gray-600 hover:text-gray-900"
        >
          Back to Home
        </button>
      </header>

      {state.location_permission_granted === null && (
        <div className="bg-yellow-50 border-l-4 border-yellow-400 p-4 rounded-md">
          <p className="text-sm text-yellow-700">App needs location permission.</p>
          <button 
            id="permission-location-allow"
            onClick={handleLocationPermission}
            className="mt-2 bg-yellow-600 text-white px-3 py-1 rounded hover:bg-yellow-700 text-sm"
          >
            Allow Location
          </button>
        </div>
      )}

      <div className="flex flex-col md:flex-row gap-6">
        {/* Filters Panel */}
        <div className="w-full md:w-1/4 bg-white p-4 shadow-sm rounded-md h-fit">
          <h2 className="text-lg font-semibold mb-4 text-slate-700">Filters</h2>
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Filter by name</label>
              <input 
                id="workspace-filter-text"
                type="text" 
                value={filterValue}
                onChange={(e) => setFilterValue(e.target.value)}
                className="w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500"
              />
            </div>
            <button 
              id="workspace-filter-include-joined"
              onClick={handleApplyFilters}
              className="w-full bg-slate-600 text-white px-4 py-2 rounded hover:bg-slate-700 transition"
            >
              Apply Filter
            </button>
          </div>

          <h2 className="text-lg font-semibold mt-8 mb-4 text-slate-700">Search</h2>
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Search workspaces</label>
              <input 
                id="workspace-search-input"
                type="text" 
                value={searchValue}
                onChange={(e) => setSearchValue(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') handleSearch();
                }}
                className="w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500"
              />
            </div>
          </div>
        </div>

        {/* Workspaces List Panel */}
        <div 
          id="workspace-list-container"
          className="w-full md:w-3/4 bg-white p-4 shadow-sm rounded-md"
          onDragStart={handleScrollIntoView}
          draggable
        >
          <div id="workspace-list" className="space-y-2">

