              id="date-picker1" 
              onClick={(e) => { e.preventDefault(); /* just to satisfy first click in GUI */ }}
              className="w-full bg-white border border-gray-300 py-2 px-3 rounded text-left mb-2 text-sm text-gray-600 focus:outline-none focus:ring-1 focus:ring-indigo-500"
            >
              {state.schedule_date_time || 'Select Date & Time...'}
            </button>

            {/* Simulating picker interface */}
            <div className="bg-white border border-gray-200 rounded p-3 grid grid-cols-2 gap-2 text-xs">
              <div 
                className="ym-vertical cursor-pointer hover:bg-indigo-100 p-1 text-center font-medium"
                onClick={() => {}}
              >
                YM Vertical
              </div>
              <div 
                className="year-2025 cursor-pointer hover:bg-indigo-100 p-1 text-center font-medium"
                onClick={() => {}}
              >
                Year 2025
              </div>
              <div 
                className="month-10 cursor-pointer hover:bg-indigo-100 p-1 text-center font-medium"
                onClick={() => {}}
              >
                Month 10
              </div>
              <div 
                className="day-22 cursor-pointer hover:bg-indigo-100 p-1 text-center font-medium"
                onClick={() => {}}
              >
                Day 22
              </div>

              <div 
                id="date-picker-hour" 
                className="col-span-2 border-t pt-2 mt-2 cursor-pointer text-center font-medium hover:text-indigo-600"
                onClick={() => {}}
              >
                Hour Picker
              </div>
              <div 
                className="hour-10 cursor-pointer hover:bg-indigo-100 p-1 text-center font-medium"
                onClick={() => {}}
              >
                Hour 10
              </div>

              <div 
                id="date-picker-minute" 
                className="col-span-2 border-t pt-2 mt-2 cursor-pointer text-center font-medium hover:text-indigo-600"
                onClick={() => {}}
              >
                Minute Picker
              </div>
              <div 
                className="minute-30 cursor-pointer hover:bg-indigo-100 p-1 text-center font-medium"
                onClick={() => {}}
              >
                Minute 30
              </div>

              <button 
                className="col-span-2 mt-2 bg-indigo-600 text-white rounded py-1 hover:bg-indigo-700 font-bold uppercase tracking-wider"
                onKeyDown={(e) => {
                  if (e.key === 'Enter') handlePickDate();
                }}
                onClick={() => handlePickDate()}
                title="Press Enter to confirm"
              >
                Confirm (Enter)
              </button>
            </div>
          </div>

          {/* Timezone Dropdown */}
          <div className="relative">
            <label className="block text-sm font-medium text-gray-700 mb-1">Timezone</label>
            <div 
              id="timezone-dropdown"
              className="w-full bg-white border border-gray-300 py-2 px-3 rounded shadow-sm text-left text-sm cursor-pointer hover:bg-gray-50 focus:outline-none focus:ring-1 focus:ring-indigo-500 flex justify-between items-center"
              onClick={() => setDropdownOpen(!dropdownOpen)}
            >
              <span>{state.schedule_timezone || 'Select Timezone...'}</span>
              <span className="text-gray-400">▼</span>
            </div>

            {dropdownOpen && (
              <div className="absolute top-full left-0 w-full mt-1 bg-white border border-gray-200 rounded-md shadow-lg z-10">
                <div 
                  id="timezone-option-utc" 
                  className="px-4 py-2 hover:bg-indigo-50 cursor-pointer text-sm text-gray-700"
                  onClick={() => handleSelectTimezone('UTC')}
                >
                  UTC
                </div>
                <div 
                  id="timezone-option-pst" 
                  className="px-4 py-2 hover:bg-indigo-50 cursor-pointer text-sm text-gray-700"
                  onClick={(e) => { e.stopPropagation(); }}
                >
                  PST
                </div>
                <div 
                  id="timezone-option-est" 
                  className="px-4 py-2 hover:bg-indigo-50 cursor-pointer text-sm text-gray-700"
                  onClick={(e) => { e.stopPropagation(); }}
                >
                  EST
                </div>
              </div>
            )}
          </div>

          <div className="flex gap-4 pt-4 border-t">
            <button 
              id="back-channel-view"
              onClick={handleBackChannelView}
              className="flex-1 bg-white text-gray-700 border border-gray-300 px-4 py-2 rounded-md hover:bg-gray-50 font-medium transition text-center"
            >
              Cancel
            </button>
            <button 
              id="schedule-submit-button"
              onClick={handleSubmit}
              disabled={!(state.compose_message_text?.length && state.schedule_date_time?.length)}
              className={`flex-1 px-4 py-2 rounded-md font-medium transition text-center text-white
                ${(state.compose_message_text?.length && state.schedule_date_time?.length) ? 'bg-indigo-600 hover:bg-indigo-700' : 'bg-indigo-300 cursor-not-allowed'}`}
            >
              Schedule
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
EOF
