{"command":"cat << 'EOF' > src/pages/CREATE_CHANNEL.tsx
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAppContext } from '../store/FsmContext';

export default function CreateChannel() {
  const navigate = useNavigate();
  const { state, updateState } = useAppContext();

  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [inviteText, setInviteText] = useState('');
  const [dropdownOpen, setDropdownOpen] = useState(false);

  const handleTypeName = (text: string) => {
    setName(text);
    updateState({ new_channel_name: text });
  };

  const handleTypeDescription = (text: string) => {
    setDescription(text);
    updateState({ new_channel_description: text });
  };

  const handleSelectPrivacy = (privacy: string) => {
    updateState({ new_channel_privacy: privacy });
    setDropdownOpen(false);
  };

  const handleAddInvite = () => {
    if (inviteText.trim()) {
      const currentInvites = state.new_channel_invite_ids || [];
      if (!currentInvites.includes(inviteText.trim())) {
        updateState({ new_channel_invite_ids: [...currentInvites, inviteText.trim()] });
      }
      setInviteText('');
    }
  };

  const handleSubmit = () => {
    if (state.new_channel_name && state.new_channel_name.length > 0) {
      navigate('/CREATE_CHANNEL_SUCCESS');
    }
  };

  const handleBackChannelList = () => {
    navigate('/CHANNEL_LIST');
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-8">
      <div className="bg-white p-8 rounded-lg shadow-lg w-full max-w-md">
        <h1 className="text-2xl font-bold text-slate-800 mb-6 border-b pb-4">Create a Channel</h1>

        <div className="space-y-5">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Name <span className="text-red-500">*</span></label>
            <input 
              id="channel-name-input"
              type="text" 
              placeholder="# e.g. project-updates"
              value={name}
              onChange={(e) => handleTypeName(e.target.value)}
              className="w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 p-2 border"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Description</label>
            <input 
              id="channel-description-input"
              type="text" 
              placeholder="What's this channel about?"
              value={description}
              onChange={(e) => handleTypeDescription(e.target.value)}
              className="w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 p-2 border"
            />
          </div>

          <div className="relative">
            <label className="block text-sm font-medium text-gray-700 mb-1">Privacy</label>
            <div 
              id="channel-privacy-dropdown"
              className="w-full bg-white border border-gray-300 py-2 px-3 rounded shadow-sm text-left text-sm cursor-pointer hover:bg-gray-50 focus:outline-none focus:ring-1 focus:ring-indigo-500 flex justify-between items-center"
              onClick={() => setDropdownOpen(!dropdownOpen)}
            >
              <span>{state.new_channel_privacy === 'public' ? '# Public - Anyone in workspace can join' : state.new_channel_privacy === 'private' ? '🔒 Private - Only invited members' : 'Select Privacy...'}</span>
              <span className="text-gray-400">▼</span>
            </div>

            {dropdownOpen && (
              <div className="absolute top-full left-0 w-full mt-1 bg-white border border-gray-200 rounded-md shadow-lg z-10">
                <div 
                  id="privacy-option-public" 
                  className="px-4 py-3 hover:bg-indigo-50 cursor-pointer text-sm text-gray-700 border-b border-gray-100"
                  onClick={() => handleSelectPrivacy('public')}
                >
                  <strong className="block text-gray-900"># Public</strong>
                  Anyone in your workspace can join
                </div>
                <div 
                  id="privacy-option-private" 
                  className="px-4 py-3 hover:bg-indigo-50 cursor-pointer text-sm text-gray-700"
                  onClick={(e) => { e.stopPropagation(); /* no-op for mock, user should click public per fsm */ }}
                >
                  <strong className="block text-gray-900">🔒 Private</strong>
                  Only invited members can join
                </div>
              </div>
            )}
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Invite Users (optional)</label>
            <input 
              id="channel-invite-input"
              type="text" 
              placeholder="Type username and press Enter"
              value={inviteText}
              onChange={(e) => setInviteText(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') {
                  e.preventDefault();
                  handleAddInvite();
                }
              }}
              className="w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 p-2 border mb-2"
            />
            {state.new_channel_invite_ids && state.new_channel_invite_ids.length > 0 && (
              <div className="flex flex-wrap gap-2 mt-2">
                {state.new_channel_invite_ids.map(id => (
                  <span key={id} className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-indigo-100 text-indigo-800">
                    {id}
                  </span>
                ))}
              </div>
            )}
          </div>

          <div className="flex gap-4 pt-6 border-t mt-6">
            <button 
              id="back-channel-list"
              onClick={handleBackChannelList}
              className="flex-1 bg-white text-gray-700 border border-gray-300 px-4 py-2 rounded-md hover:bg-gray-50 font-medium transition text-center"
            >
              Cancel
            </button>
            <button 
              id="create-channel-submit"
              onClick={handleSubmit}
              disabled={!(state.new_channel_name && state.new_channel_name.length > 0)}
              className={`flex-1 px-4 py-2 rounded-md font-medium transition text-center text-white
                ${(state.new_channel_name && state.new_channel_name.length > 0) ? 'bg-indigo-600 hover:bg-indigo-700' : 'bg-indigo-300 cursor-not-allowed'}`}
            >
              Create Channel
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
EOF
"}

