import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAppContext } from '../store/FsmContext';

export default function DmList() {
  const navigate = useNavigate();
  const { state, updateState } = useAppContext();

  const [filterValue, setFilterValue] = useState('');
  const [searchValue, setSearchValue] = useState('');

  const handleApplyFilters = () => {
    updateState({ dm_list_filters_applied: true });
  };

  const handleOpenFiltered = (dmId: string) => {
    if (state.dm_list_filters_applied === true) {
      updateState({ dm_list_filters_applied: null, selected_dm_id: dmId });
      navigate('/DM_VIEW');
    }
  };

  const handleSearch = () => {
    updateState({ matched_dm_id: 'dm_matched_1', dm_list_has_searched: true });
  };

  const handleOpenMatched = (dmId: string) => {
    if (state.matched_dm_id && state.dm_list_has_searched === true) {
      updateState({ selected_dm_id: dmId, dm_list_has_searched: null });
      navigate('/DM_VIEW');
    }
  };

  const handleScrollIntoView = () => {
    updateState({ dm_list_viewport_anchor_id: 'dm_anchor_1' });
  };

  const handleOpenAny = (dmId: string) => {
    if (state.dm_list_viewport_anchor_id) {
      updateState({ selected_dm_id: dmId, dm_list_viewport_anchor_id: null });
      navigate('/DM_VIEW');
    }
  };

  const handleGoCreateDm = () => {
    navigate('/CREATE_DM');
  };

  const handleBackChannelList = () => {
    navigate('/CHANNEL_LIST');
  };

  return (
    <div className="flex h-screen overflow-hidden bg-slate-50">
      {/* Sidebar Navigation */}
      <aside className="w-64 bg-slate-800 text-white flex flex-col p-4 shadow-lg h-full">
        <h2 className="text-xl font-bold mb-6 truncate" title={state.selected_team_id || "Workspace"}>
          {state.selected_team_id || "Workspace"}
        </h2>

        <div className="flex-1 space-y-4">
          <div>
            <button 
              id="back-channel-list"
              onClick={handleBackChannelList}
              className="text-left w-full text-slate-300 hover:text-white text-sm py-1 font-medium flex items-center gap-2 mb-4"
            >
              &larr; Back to Channels
            </button>
            <hr className="border-slate-700 my-4" />
            <div className="flex justify-between items-center mb-2 text-slate-400 text-xs uppercase font-semibold">
              <span>Direct Messages</span>
              <button 
                id="button-new-dm"
                onClick={handleGoCreateDm}
                className="hover:text-white px-2 py-1 bg-slate-700 rounded"
              >
                +
              </button>
            </div>
          </div>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col min-w-0 bg-white">
        <header className="p-4 border-b border-gray-200 flex flex-col md:flex-row justify-between items-center gap-4">
          <h1 className="text-xl font-bold text-gray-800">Direct Messages</h1>
          <div className="flex items-center space-x-4">
            {/* Search */}
            <div className="relative">
              <input 
                id="dm-search-input"
                type="text" 
                placeholder="Search DMs"
                value={searchValue}
                onChange={(e) => setSearchValue(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') handleSearch();
                }}
                className="w-full pl-3 pr-4 py-2 text-sm border-gray-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500"
              />
            </div>
            {/* Filter */}
            <div className="flex space-x-2">
              <input 
                id="dm-filter-text"
                type="text" 
                placeholder="Filter name"
                value={filterValue}
                onChange={(e) => setFilterValue(e.target.value)}
                className="w-32 px-2 py-1 text-sm border-gray-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500"
              />
              <button 
                id="dm-filter-include-recent"
                onClick={handleApplyFilters}
                className="bg-indigo-600 text-white px-3 py-1 rounded text-sm hover:bg-indigo-700 transition"
              >
                Filter
              </button>
            </div>
          </div>
        </header>

        {/* DM List */}
        <div 
          id="dm-list-container"
          className="flex-1 overflow-y-auto p-4 bg-gray-50"
          onDragStart={handleScrollIntoView}
          draggable
        >
          <div id="dm-list" className="space-y-2">

            {/* Filtered Result */}
            {state.dm_list_filters_applied && (
              <div 
                className="dm-row-filtered bg-white border border-gray-200 p-4 rounded-md shadow-sm hover:shadow-md cursor-pointer flex justify-between items-center"
                onClick={() => handleOpenFiltered('dm_filtered')}
              >
                <div className="flex items-center gap-3">
                  <div className="w-8 h-8 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-800 font-bold text-xs">F</div>
                  <div>
                    <h3 className="font-semibold text-gray-800">Filtered User</h3>
                    <p className="text-sm text-gray-500">Matches filter criteria</p>
                  </div>
                </div>
                <span className="text-gray-400">&rarr;</span>
              </div>
            )}

            {/* Matched Result */}
            {state.matched_dm_id && state.dm_list_has_searched && (
              <div 
                className="dm-row-matched bg-white border-l-4 border-l-indigo-500 border border-gray-200 p-4 rounded-md shadow-sm hover:shadow-md cursor-pointer flex justify-between items-center"
                onClick={() => handleOpenMatched(state.matched_dm_id!)}
              >
                <div className="flex items-center gap-3">
                  <div className="w-8 h-8 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-800 font-bold text-xs">M</div>
                  <div>
                    <h3 className="font-semibold text-gray-800">{state.matched_dm_id}</h3>
                    <p className="text-sm text-gray-500">Matches search query</p>
                  </div>
                </div>
                <span className="text-gray-400">&rarr;</span>
              </div>
            )}

            {/* Anchored / Visible Result */}
            {state.dm_list_viewport_anchor_id && (
              <div 
                className="dm-row-visible bg-white border border-gray-200 p-4 rounded-md shadow-sm hover:shadow-md cursor-pointer flex justify-between items-center"
                onClick={() => handleOpenAny('dm_visible_1')}
              >
                <div className="flex items-center gap-3">
                  <div className="w-8 h-8 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-800 font-bold text-xs">V</div>
                  <div>
                    <h3 className="font-semibold text-gray-800">Visible User</h3>
                    <p className="text-sm text-gray-500">Visible from scrolling</p>
                  </div>
                </div>
                <span className="text-gray-400">&rarr;</span>
              </div>
            )}

            {!state.dm_list_filters_applied && !state.dm_list_has_searched && !state.dm_list_viewport_anchor_id && (
              <div className="flex items-center justify-center h-full text-gray-400 italic">
                No active filter, search, or scroll applied yet.
              </div>
            )}
          </div>
        </div>
      </main>
    </div>
  );
}
EOF
"}

