import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAppContext } from '../store/FsmContext';

export default function CreateDm() {
  const navigate = useNavigate();
  const { state, updateState } = useAppContext();

  const [recipientText, setRecipientText] = useState('');
  const [initialMessage, setInitialMessage] = useState('');

  const handleAddRecipient = () => {
    if (recipientText.trim()) {
      const currentRecipients = state.dm_recipient_ids || [];
      if (!currentRecipients.includes(recipientText.trim())) {
        updateState({ dm_recipient_ids: [...currentRecipients, recipientText.trim()] });
      }
      setRecipientText('');
    }
  };

  const handleTypeInitialMessage = (text: string) => {
    setInitialMessage(text);
    updateState({ dm_initial_message: text });
  };

  const handleSubmit = () => {
    if (state.dm_initial_message && state.dm_initial_message.length > 0) {
      navigate('/CREATE_DM_SUCCESS');
    }
  };

  const handleBackDmList = () => {
    navigate('/DM_LIST');
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-8">
      <div className="bg-white p-8 rounded-lg shadow-lg w-full max-w-md">
        <h1 className="text-2xl font-bold text-slate-800 mb-6 border-b pb-4">New Direct Message</h1>

        <div className="space-y-5">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">To: (Add Recipients)</label>
            <input 
              id="dm-recipient-input"
              type="text" 
              placeholder="Type a name and press Enter"
              value={recipientText}
              onChange={(e) => setRecipientText(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') {
                  e.preventDefault();
                  handleAddRecipient();
                }
              }}
              className="w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 p-2 border mb-2"
            />
            {state.dm_recipient_ids && state.dm_recipient_ids.length > 0 && (
              <div className="flex flex-wrap gap-2 mt-2 p-2 border border-gray-100 rounded bg-gray-50 min-h-[40px]">
                {state.dm_recipient_ids.map(id => (
                  <span key={id} className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-indigo-100 text-indigo-800">
                    {id}
                  </span>
                ))}
              </div>
            )}
            {(!state.dm_recipient_ids || state.dm_recipient_ids.length === 0) && (
               <div className="text-xs text-gray-400 mt-1">No recipients added yet.</div>
            )}
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Message <span className="text-red-500">*</span></label>
            <textarea 
              id="dm-initial-message-input"
              placeholder="Start a new conversation..."
              value={initialMessage}
              onChange={(e) => handleTypeInitialMessage(e.target.value)}
              className="w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 p-3 border min-h-[120px] resize-none"
            ></textarea>
          </div>

          <div className="flex gap-4 pt-6 border-t mt-6">
            <button 
              id="back-dm-list"
              onClick={handleBackDmList}
              className="flex-1 bg-white text-gray-700 border border-gray-300 px-4 py-2 rounded-md hover:bg-gray-50 font-medium transition text-center"
            >
              Cancel
            </button>
            <button 
              id="create-dm-submit"
              onClick={handleSubmit}
              disabled={!(state.dm_initial_message && state.dm_initial_message.length > 0)}
              className={`flex-1 px-4 py-2 rounded-md font-medium transition text-center text-white
                ${(state.dm_initial_message && state.dm_initial_message.length > 0) ? 'bg-indigo-600 hover:bg-indigo-700' : 'bg-indigo-300 cursor-not-allowed'}`}
            >
              Start DM
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
