import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAppContext } from '../store/FsmContext';

export default function ProfileSettings() {
  const navigate = useNavigate();
  const { state, updateState } = useAppContext();

  const [displayName, setDisplayName] = useState(state.profile_display_name || '');
  const [title, setTitle] = useState(state.profile_title || '');
  const [dropdownOpen, setDropdownOpen] = useState(false);

  const handleTypeDisplayName = (text: string) => {
    setDisplayName(text);
    updateState({ profile_display_name: text });
  };

  const handleTypeTitle = (text: string) => {
    setTitle(text);
    updateState({ profile_title: text });
  };

  const handleSelectTimezone = (tz: string) => {
    updateState({ profile_timezone: tz });
    setDropdownOpen(false);
  };

  const handleSave = () => {
    if (state.profile_display_name && state.profile_display_name.length > 0) {
      navigate('/UPDATE_PROFILE_SUCCESS');
    }
  };

  const handleBackHome = () => {
    navigate('/HOME');
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col items-center py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-md w-full bg-white p-8 rounded-lg shadow-md">
        <div className="flex justify-between items-center mb-6 border-b pb-4">
          <h2 className="text-2xl font-bold text-gray-900">Edit Profile</h2>
          <button 
            id="back-home"
            onClick={handleBackHome}
            className="text-gray-500 hover:text-gray-700 font-medium text-sm"
          >
            Close
          </button>
        </div>

        <div className="space-y-6">
          <div className="flex items-center space-x-4 mb-6">
            <div className="h-20 w-20 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-500 text-3xl font-bold">
              {displayName ? displayName.charAt(0).toUpperCase() : 'U'}
            </div>
            <div>
              <button className="bg-white border border-gray-300 rounded-md px-3 py-1.5 text-sm font-medium text-gray-700 hover:bg-gray-50">
                Upload an Image
              </button>
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Display Name <span className="text-red-500">*</span></label>
            <input 
              id="profile-display-name-input"
              type="text" 
              placeholder="How you'd like to be called"
              value={displayName}
              onChange={(e) => handleTypeDisplayName(e.target.value)}
              className="w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 p-2 border"
            />
            <p className="mt-1 text-xs text-gray-500">This could be your first name, or a nickname.</p>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">What I do</label>
            <input 
              id="profile-title-input"
              type="text" 
              placeholder="e.g. Engineering Manager"
              value={title}
              onChange={(e) => handleTypeTitle(e.target.value)}
              className="w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 p-2 border"
            />
          </div>

          <div className="relative">
            <label className="block text-sm font-medium text-gray-700 mb-1">Timezone</label>
            <div 
              id="profile-timezone-dropdown"
              className="w-full bg-white border border-gray-300 py-2 px-3 rounded shadow-sm text-left cursor-pointer hover:bg-gray-50 focus:outline-none focus:ring-1 focus:ring-indigo-500 flex justify-between items-center"
              onClick={() => setDropdownOpen(!dropdownOpen)}
            >
              <span>{state.profile_timezone || 'Select Timezone...'}</span>
              <span className="text-gray-400">▼</span>
            </div>

            {dropdownOpen && (
              <div className="absolute top-full left-0 w-full mt-1 bg-white border border-gray-200 rounded-md shadow-lg z-10 max-h-48 overflow-y-auto">
                <div 
                  id="profile-timezone-utc" 
                  className="px-4 py-2 hover:bg-indigo-50 cursor-pointer text-sm text-gray-700"
                  onClick={() => handleSelectTimezone('UTC')}
                >
                  (UTC+00:00) Coordinated Universal Time
                </div>
                <div 
                  id="profile-timezone-pst" 
                  className="px-4 py-2 hover:bg-indigo-50 cursor-pointer text-sm text-gray-700"
                  onClick={(e) => { e.stopPropagation(); }}
                >
                  (UTC-08:00) Pacific Time (US & Canada)
                </div>
                <div 
                  id="profile-timezone-est" 
                  className="px-4 py-2 hover:bg-indigo-50 cursor-pointer text-sm text-gray-700"
                  onClick={(e) => { e.stopPropagation(); }}
                >
                  (UTC-05:00) Eastern Time (US & Canada)
                </div>
              </div>
            )}
          </div>

          <div className="pt-4 flex justify-end">
            <button 
              id="profile-save-button"
              onClick={handleSave}
              disabled={!(state.profile_display_name && state.profile_display_name.length > 0)}
              className={`px-6 py-2 rounded-md font-medium transition text-white
                ${(state.profile_display_name && state.profile_display_name.length > 0) ? 'bg-indigo-600 hover:bg-indigo-700' : 'bg-indigo-300 cursor-not-allowed'}`}
            >
              Save Changes
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
EOF
